import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ref, onValue, update } from 'firebase/database';
import { db } from '../firebase';

function SeriesDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [series, setSeries] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedUser, setSelectedUser] = useState('mucahit');

  useEffect(() => {
    const seriesRef = ref(db, `series/${id}`);
    const unsubscribe = onValue(seriesRef, (snapshot) => {
      if (snapshot.exists()) {
        setSeries(snapshot.val());
      } else {
        setError('Dizi bulunamadı');
      }
      setLoading(false);
    }, (error) => {
      setError('Dizi yüklenirken bir hata oluştu');
      setLoading(false);
    });

    return () => unsubscribe();
  }, [id]);

  const toggleEpisodeWatched = async (season, episode) => {
    if (!series || !series.watchedEpisodes) return;

    const episodeKey = `${season}-${episode}`;
    const currentValue = series.watchedEpisodes[selectedUser]?.[episodeKey] || false;

    try {
      const updates = {
        [`series/${id}/watchedEpisodes/${selectedUser}/${episodeKey}`]: !currentValue
      };
      await update(ref(db), updates);
    } catch (error) {
      console.error('Bölüm güncelleme hatası:', error);
    }
  };

  const toggleSeasonWatched = async (season) => {
    if (!series || !series.watchedEpisodes || !series.seasonsData) return;

    const episodeCount = series.seasonsData[season]?.episodeCount || 0;
    const allEpisodes = Array.from({ length: episodeCount }, (_, i) => i + 1);
    const seasonEpisodes = allEpisodes.reduce((acc, episode) => {
      const episodeKey = `${season}-${episode}`;
      acc[episodeKey] = !allEpisodes.every(ep => 
        series.watchedEpisodes[selectedUser]?.[`${season}-${ep}`]
      );
      return acc;
    }, {});

    try {
      const updates = Object.entries(seasonEpisodes).reduce((acc, [key, value]) => {
        acc[`series/${id}/watchedEpisodes/${selectedUser}/${key}`] = value;
        return acc;
      }, {});
      await update(ref(db), updates);
    } catch (error) {
      console.error('Sezon güncelleme hatası:', error);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-purple-50 to-pink-50">
        <div className="animate-spin rounded-full h-12 w-12 border-4 border-purple-500 border-t-transparent"></div>
      </div>
    );
  }

  if (error || !series) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-purple-50 to-pink-50">
        <div className="text-center">
          <h2 className="text-2xl font-bold text-gray-800 mb-4">Hata</h2>
          <p className="text-gray-600 mb-4">{error || 'Dizi bulunamadı'}</p>
          <button
            onClick={() => navigate('/series')}
            className="px-4 py-2 bg-gradient-to-r from-purple-600 to-pink-600 text-white rounded-lg hover:from-purple-700 hover:to-pink-700 transition duration-200"
          >
            Dizilere Dön
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen relative">
      {/* Yarı saydam arka plan */}
      <div 
        className="fixed inset-0 opacity-20"
        style={{
          backgroundImage: `url(/images/background.jpg)`,
          backgroundSize: 'cover',
          backgroundPosition: 'center',
          backgroundRepeat: 'no-repeat',
          width: '100vw',
          height: '100vh',
          zIndex: -1
        }}
      />
      
      {/* Gradient overlay */}
      <div 
        className="fixed inset-0 bg-gradient-to-br from-purple-50/90 to-pink-50/90"
        style={{ 
          zIndex: -1,
          width: '100vw',
          height: '100vh'
        }}
      />

      <div className="relative py-8 px-4">
        <div className="max-w-4xl mx-auto">
          <div className="bg-white/90 backdrop-blur-sm rounded-xl shadow-lg overflow-hidden">
            {/* Dizi Başlığı ve Kapak */}
            <div className="relative h-64 bg-gradient-to-r from-purple-600 to-pink-600">
              {series.coverImage && (
                <img
                  src={series.coverImage}
                  alt={series.title}
                  className="absolute inset-0 w-full h-full object-cover opacity-30"
                />
              )}
              <div className="absolute inset-0 flex items-center justify-between p-8">
                <div className="flex-1">
                  <h1 className="text-4xl font-bold text-white mb-2">{series.title}</h1>
                  <p className="text-white/90">
                    {series.totalSeasons} Sezon
                  </p>
                </div>
                {series.coverImage && (
                  <img
                    src={series.coverImage}
                    alt={series.title}
                    className="h-48 w-32 object-cover rounded-lg shadow-lg"
                  />
                )}
              </div>
            </div>

            {/* Kullanıcı Seçimi */}
            <div className="p-6 border-b border-gray-200">
              <div className="flex space-x-4">
                <button
                  onClick={() => setSelectedUser('mucahit')}
                  className={`px-6 py-3 rounded-lg font-medium transition duration-200 ${
                    selectedUser === 'mucahit'
                      ? 'bg-blue-600 text-white'
                      : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                  }`}
                >
                  Mücahit
                </button>
                <button
                  onClick={() => setSelectedUser('beyza')}
                  className={`px-6 py-3 rounded-lg font-medium transition duration-200 ${
                    selectedUser === 'beyza'
                      ? 'bg-pink-600 text-white'
                      : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                  }`}
                >
                  Beyza
                </button>
              </div>
            </div>

            {/* Sezonlar ve Bölümler */}
            <div className="p-6">
              <div className="space-y-8">
                {Array.from({ length: series.totalSeasons }, (_, i) => i + 1).map((season) => (
                  <div key={season} className="space-y-4">
                    <div className="flex items-center justify-between">
                      <h2 className="text-xl font-semibold text-gray-800">
                        Sezon {season}
                      </h2>
                      <button
                        onClick={() => toggleSeasonWatched(season)}
                        className={`px-4 py-2 rounded-lg font-medium transition duration-200 ${
                          selectedUser === 'mucahit'
                            ? 'bg-blue-100 text-blue-700 hover:bg-blue-200'
                            : 'bg-pink-100 text-pink-700 hover:bg-pink-200'
                        }`}
                      >
                        Tüm Bölümleri {
                          Array.from({ length: series.seasonsData[season]?.episodeCount || 0 }, (_, i) => i + 1)
                            .every(ep => series.watchedEpisodes[selectedUser]?.[`${season}-${ep}`])
                            ? 'İzlenmiyor Yap'
                            : 'İzlendi Yap'
                        }
                      </button>
                    </div>

                    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3">
                      {Array.from({ length: series.seasonsData[season]?.episodeCount || 0 }, (_, i) => i + 1).map((episode) => (
                        <button
                          key={episode}
                          onClick={() => toggleEpisodeWatched(season, episode)}
                          className={`
                            p-3 rounded-lg font-medium transition duration-200
                            ${series.watchedEpisodes[selectedUser]?.[`${season}-${episode}`]
                              ? selectedUser === 'mucahit'
                                ? 'bg-blue-600 text-white'
                                : 'bg-pink-600 text-white'
                              : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                            }
                          `}
                        >
                          Bölüm {episode}
                        </button>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Alt Butonlar */}
            <div className="p-6 bg-gray-50/50 border-t border-gray-200">
              <div className="flex justify-between">
                <button
                  onClick={() => navigate('/series')}
                  className="px-4 py-2 text-gray-600 hover:text-gray-800 transition duration-200"
                >
                  ← Dizilere Dön
                </button>
                <div className="space-x-4">
                  <button
                    onClick={() => navigate(`/series/${id}/edit`)}
                    className="px-4 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50 transition duration-200"
                  >
                    Düzenle
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
